 <?php $__env->startSection('title','Monitoring Prodi'); ?> <?php $__env->startSection('content'); ?><div class="container py-4"><h2 class="fw-bold">Monitoring Seluruh Laboratorium</h2><p class="text-secondary">Prodi melihat aktivitas lintas laboratorium.</p><div class="row g-4"><?php $__currentLoopData = $labs; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $lab): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php $active=$lab->testingServices->sum('active_requests_count'); $done=$lab->testingServices->sum('completed_requests_count'); ?><div class="col-lg-4"><div class="card border-0 shadow-sm h-100"><div class="card-body"><span class="badge text-bg-primary"><?php echo e($lab->code); ?></span><h4 class="mt-2"><?php echo e($lab->name); ?></h4><div class="row g-2 mt-2"><div class="col-6"><div class="p-3 bg-light rounded"><small>Kelas</small><div class="h3 mb-0"><?php echo e($lab->classes_count); ?></div></div></div><div class="col-6"><div class="p-3 bg-light rounded"><small>Pengujian Aktif</small><div class="h3 mb-0"><?php echo e($active); ?></div></div></div><div class="col-6"><div class="p-3 bg-light rounded"><small>Pengujian Selesai</small><div class="h3 mb-0"><?php echo e($done); ?></div></div></div><div class="col-6"><div class="p-3 bg-light rounded"><small>Personel</small><div class="h3 mb-0"><?php echo e($lab->users_count); ?></div></div></div></div></div></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div></div><?php $__env->stopSection(); ?>
